`timescale 1ns/1ps

// Reads a completed event window out of the metadata evidence ring and streams
// it as newline-terminated ASCII over UART. The sequencer runs in the event
// (pixel) clock domain so it can read the ring directly; each generated byte
// crosses into the UART clock domain through a two-way toggle handshake, which
// costs nothing at 115200 baud.
//
// Line format, fixed width so the host can parse without a real parser:
//
//   EV,<seq:3>,<idx:2>,<frame:10>,<ts:10>,<stage:1>,<risk:1>,<zone:1>,
//      <code:3>,<mp:3>,<mo:3>,<mf:3>,<cfg:3>,<hl:3>\n
//   EO,<seq:3>,<count:3>\n
module evidence_dump #(
    parameter integer UART_CLK_HZ    = 50000000,
    parameter integer BAUD_RATE      = 115200,
    parameter integer CAPTURE_LENGTH = 65,
    parameter integer INDEX_WIDTH    = 7,
    parameter integer SEQ_WIDTH      = 8,
    parameter integer STREAM_OUTPUT = 0
) (
    // Event (pixel) clock domain
    input                        ev_clk,
    input                        ev_rst,
    input                        ev_start,
    input                        ring_available,
    input                        ring_read_valid,
    input  [131:0]               ring_read_data,
    input  [SEQ_WIDTH-1:0]       ring_seq,
    output reg                   ring_read_req,
    output reg [INDEX_WIDTH-1:0] ring_read_index,
    output reg                   busy,
    // UART clock domain
    input                        uart_clk,
    input                        uart_rst,
    output                       uart_txd,
    output                       stream_valid,stream_last,
    output [7:0]                 stream_data,
    input                        stream_ready
);

    localparam integer RECORD_LAST  = 6'd61;
    localparam integer END_LAST     = 6'd10;

    localparam [2:0] S_IDLE = 3'd0;
    localparam [2:0] S_REQ  = 3'd1;
    localparam [2:0] S_WAIT = 3'd2;
    localparam [2:0] S_BCD  = 3'd3;
    localparam [2:0] S_EMIT = 3'd4;
    localparam [2:0] S_NEXT = 3'd5;

    localparam [0:0] KIND_REC = 1'b0;
    localparam [0:0] KIND_END = 1'b1;

    reg [2:0]  state;
    reg [0:0]  line_kind;
    reg [5:0]  line_pos;
    reg [6:0]  record_index;
    reg        byte_pending;
    reg [7:0]  byte_hold;
    reg        byte_toggle;
    reg [SEQ_WIDTH-1:0] win_seq;

    // Latched record fields.
    reg [31:0] r_frame;
    reg [31:0] r_timestamp;
    reg [3:0]  r_stage;
    reg [3:0]  r_risk;
    reg [3:0]  r_zone;
    reg [7:0]  r_code;
    reg [7:0]  r_mp;
    reg [7:0]  r_mo;
    reg [7:0]  r_mf;
    reg [7:0]  r_cfg;
    reg [7:0]  r_hl;
    reg [7:0]  r_seq;

    // BCD results for the two 32-bit fields.
    reg [39:0] frame_bcd;
    reg [39:0] timestamp_bcd;
    wire       frame_bcd_start;
    wire       timestamp_bcd_start;
    wire       frame_bcd_busy;
    wire       timestamp_bcd_busy;
    wire       frame_bcd_done;
    wire       timestamp_bcd_done;
    wire [39:0] frame_bcd_out;
    wire [39:0] timestamp_bcd_out;

    assign frame_bcd_start     = (state == S_BCD) && !frame_bcd_busy &&
                                 !frame_bcd_done;
    assign timestamp_bcd_start = (state == S_BCD) && !timestamp_bcd_busy &&
                                 !timestamp_bcd_done;

    u32_to_bcd frame_converter (
        .clk    (ev_clk),
        .rst    (ev_rst),
        .start  (frame_bcd_start),
        .value  (r_frame),
        .busy   (frame_bcd_busy),
        .done   (frame_bcd_done),
        .digits (frame_bcd_out)
    );

    u32_to_bcd timestamp_converter (
        .clk    (ev_clk),
        .rst    (ev_rst),
        .start  (timestamp_bcd_start),
        .value  (r_timestamp),
        .busy   (timestamp_bcd_busy),
        .done   (timestamp_bcd_done),
        .digits (timestamp_bcd_out)
    );

    function [7:0] d3;
        input [7:0] v;
        input [1:0] p;
        reg [7:0] hundreds;
        reg [7:0] tens;
        reg [7:0] ones;
        begin
            hundreds = v / 8'd100;
            tens     = (v / 8'd10) % 8'd10;
            ones     = v % 8'd10;
            if (p == 2'd0)
                d3 = 8'h30 + hundreds;
            else if (p == 2'd1)
                d3 = 8'h30 + tens;
            else
                d3 = 8'h30 + ones;
        end
    endfunction

    function [7:0] d2;
        input [6:0] v;
        input       tens_place;
        begin
            if (tens_place)
                d2 = 8'h30 + (v / 7'd10);
            else
                d2 = 8'h30 + (v % 7'd10);
        end
    endfunction

    function [7:0] d1;
        input [3:0] v;
        begin
            d1 = 8'h30 + {4'd0, v};
        end
    endfunction

    function [7:0] bd;
        input [39:0] b;
        input [3:0]  p;
        begin
            case (p)
                4'd0:    bd = 8'h30 + b[39:36];
                4'd1:    bd = 8'h30 + b[35:32];
                4'd2:    bd = 8'h30 + b[31:28];
                4'd3:    bd = 8'h30 + b[27:24];
                4'd4:    bd = 8'h30 + b[23:20];
                4'd5:    bd = 8'h30 + b[19:16];
                4'd6:    bd = 8'h30 + b[15:12];
                4'd7:    bd = 8'h30 + b[11:8];
                4'd8:    bd = 8'h30 + b[7:4];
                default: bd = 8'h30 + b[3:0];
            endcase
        end
    endfunction

    function [7:0] record_byte;
        input [5:0] pos;
        begin
            if (pos == 6'd0)       record_byte = "E";
            else if (pos == 6'd1)  record_byte = "V";
            else if (pos == 6'd2)  record_byte = ",";
            else if (pos == 6'd3)  record_byte = d3(r_seq, 2'd0);
            else if (pos == 6'd4)  record_byte = d3(r_seq, 2'd1);
            else if (pos == 6'd5)  record_byte = d3(r_seq, 2'd2);
            else if (pos == 6'd6)  record_byte = ",";
            else if (pos == 6'd7)  record_byte = d2(record_index, 1'b1);
            else if (pos == 6'd8)  record_byte = d2(record_index, 1'b0);
            else if (pos == 6'd9)  record_byte = ",";
            else if (pos >= 6'd10 && pos <= 6'd19)
                record_byte = bd(frame_bcd, pos - 6'd10);
            else if (pos == 6'd20) record_byte = ",";
            else if (pos >= 6'd21 && pos <= 6'd30)
                record_byte = bd(timestamp_bcd, pos - 6'd21);
            else if (pos == 6'd31) record_byte = ",";
            else if (pos == 6'd32) record_byte = d1(r_stage);
            else if (pos == 6'd33) record_byte = ",";
            else if (pos == 6'd34) record_byte = d1(r_risk);
            else if (pos == 6'd35) record_byte = ",";
            else if (pos == 6'd36) record_byte = d1(r_zone);
            else if (pos == 6'd37) record_byte = ",";
            else if (pos == 6'd38) record_byte = d3(r_code, 2'd0);
            else if (pos == 6'd39) record_byte = d3(r_code, 2'd1);
            else if (pos == 6'd40) record_byte = d3(r_code, 2'd2);
            else if (pos == 6'd41) record_byte = ",";
            else if (pos == 6'd42) record_byte = d3(r_mp, 2'd0);
            else if (pos == 6'd43) record_byte = d3(r_mp, 2'd1);
            else if (pos == 6'd44) record_byte = d3(r_mp, 2'd2);
            else if (pos == 6'd45) record_byte = ",";
            else if (pos == 6'd46) record_byte = d3(r_mo, 2'd0);
            else if (pos == 6'd47) record_byte = d3(r_mo, 2'd1);
            else if (pos == 6'd48) record_byte = d3(r_mo, 2'd2);
            else if (pos == 6'd49) record_byte = ",";
            else if (pos == 6'd50) record_byte = d3(r_mf, 2'd0);
            else if (pos == 6'd51) record_byte = d3(r_mf, 2'd1);
            else if (pos == 6'd52) record_byte = d3(r_mf, 2'd2);
            else if (pos == 6'd53) record_byte = ",";
            else if (pos == 6'd54) record_byte = d3(r_cfg, 2'd0);
            else if (pos == 6'd55) record_byte = d3(r_cfg, 2'd1);
            else if (pos == 6'd56) record_byte = d3(r_cfg, 2'd2);
            else if (pos == 6'd57) record_byte = ",";
            else if (pos == 6'd58) record_byte = d3(r_hl, 2'd0);
            else if (pos == 6'd59) record_byte = d3(r_hl, 2'd1);
            else if (pos == 6'd60) record_byte = d3(r_hl, 2'd2);
            else                   record_byte = 8'h0a;
        end
    endfunction

    function [7:0] end_byte;
        input [5:0] pos;
        begin
            if (pos == 6'd0)       end_byte = "E";
            else if (pos == 6'd1)  end_byte = "O";
            else if (pos == 6'd2)  end_byte = ",";
            else if (pos == 6'd3)  end_byte = d3(win_seq, 2'd0);
            else if (pos == 6'd4)  end_byte = d3(win_seq, 2'd1);
            else if (pos == 6'd5)  end_byte = d3(win_seq, 2'd2);
            else if (pos == 6'd6)  end_byte = ",";
            else if (pos == 6'd7)  end_byte = d3(CAPTURE_LENGTH[7:0], 2'd0);
            else if (pos == 6'd8)  end_byte = d3(CAPTURE_LENGTH[7:0], 2'd1);
            else if (pos == 6'd9)  end_byte = d3(CAPTURE_LENGTH[7:0], 2'd2);
            else                   end_byte = 8'h0a;
        end
    endfunction

    wire [7:0] line_byte = (line_kind == KIND_REC) ?
                           record_byte(line_pos) : end_byte(line_pos);
    wire [5:0] line_last = (line_kind == KIND_REC) ? RECORD_LAST : END_LAST;

    // Acknowledgement synchronizer in the event domain.
    (* ASYNC_REG = "TRUE" *) reg ack_meta;
    (* ASYNC_REG = "TRUE" *) reg ack_sync;
    wire byte_acked = (ack_sync == byte_toggle);

    always @(posedge ev_clk) begin
        if (ev_rst) begin
            ack_meta   <= 1'b0;
            ack_sync   <= 1'b0;
            byte_hold  <= 8'd0;
            byte_toggle<= 1'b0;
            byte_pending <= 1'b0;
            ring_read_req   <= 1'b0;
            ring_read_index <= {INDEX_WIDTH{1'b0}};
            state      <= S_IDLE;
            busy       <= 1'b0;
            line_kind  <= KIND_REC;
            line_pos   <= 6'd0;
            record_index <= 7'd0;
            win_seq    <= {SEQ_WIDTH{1'b0}};
            r_frame    <= 32'd0;
            r_timestamp<= 32'd0;
            r_stage    <= 4'd0;
            r_risk     <= 4'd0;
            r_zone     <= 4'd0;
            r_code     <= 8'd0;
            r_mp       <= 8'd0;
            r_mo       <= 8'd0;
            r_mf       <= 8'd0;
            r_cfg      <= 8'd0;
            r_hl       <= 8'd0;
            r_seq      <= 8'd0;
            frame_bcd  <= 40'd0;
            timestamp_bcd <= 40'd0;
        end else begin
            ack_meta <= ack_toggle;
            ack_sync <= ack_meta;
            ring_read_req <= 1'b0;

            case (state)
                S_IDLE: begin
                    busy <= 1'b0;
                    if (ev_start && ring_available) begin
                        busy         <= 1'b1;
                        record_index <= 7'd0;
                        win_seq      <= ring_seq;
                        line_kind    <= KIND_REC;
                        line_pos     <= 6'd0;
                        byte_pending <= 1'b0;
                        state        <= S_REQ;
                    end
                end

                S_REQ: begin
                    ring_read_req   <= 1'b1;
                    ring_read_index <= record_index;
                    state           <= S_WAIT;
                end

                S_WAIT: begin
                    if (ring_read_valid) begin
                        r_frame     <= ring_read_data[131:100];
                        r_timestamp <= ring_read_data[99:68];
                        r_stage     <= ring_read_data[67:64];
                        r_risk      <= ring_read_data[63:60];
                        r_zone      <= ring_read_data[59:56];
                        r_code      <= ring_read_data[55:48];
                        r_mp        <= ring_read_data[47:40];
                        r_mo        <= ring_read_data[39:32];
                        r_mf        <= ring_read_data[31:24];
                        r_cfg       <= ring_read_data[23:16];
                        r_hl        <= ring_read_data[15:8];
                        r_seq       <= ring_read_data[7:0];
                        state       <= S_BCD;
                    end
                end

                S_BCD: begin
                    if (frame_bcd_done && timestamp_bcd_done) begin
                        frame_bcd     <= frame_bcd_out;
                        timestamp_bcd <= timestamp_bcd_out;
                        line_pos      <= 6'd0;
                        state         <= S_EMIT;
                    end
                end

                S_EMIT: begin
                    if (!byte_pending) begin
                        byte_hold    <= line_byte;
                        byte_toggle  <= ~byte_toggle;
                        byte_pending <= 1'b1;
                    end else if (byte_acked) begin
                        byte_pending <= 1'b0;
                        if (line_pos == line_last)
                            state <= S_NEXT;
                        else
                            line_pos <= line_pos + 6'd1;
                    end
                end

                S_NEXT: begin
                    if (line_kind == KIND_REC) begin
                        if (record_index + 7'd1 >= CAPTURE_LENGTH[6:0]) begin
                            line_kind <= KIND_END;
                            line_pos  <= 6'd0;
                            state     <= S_EMIT;
                        end else begin
                            record_index <= record_index + 7'd1;
                            state        <= S_REQ;
                        end
                    end else begin
                        busy  <= 1'b0;
                        state <= S_IDLE;
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

    // ---------------------------------------------------------------------
    // UART clock domain: consume one byte at a time and shift it out.
    // ---------------------------------------------------------------------
    localparam [1:0] U_IDLE       = 2'd0;
    localparam [1:0] U_WAIT_START = 2'd1;
    localparam [1:0] U_WAIT_DONE  = 2'd2;

    reg [1:0]  u_state;
    reg        uart_start;
    reg [7:0]  tx_byte;
    reg        ack_toggle;
    reg        req_seen;
    (* ASYNC_REG = "TRUE" *) reg req_meta;
    (* ASYNC_REG = "TRUE" *) reg req_sync;
    wire       uart_busy;

    always @(posedge uart_clk) begin
        if (uart_rst) begin
            u_state    <= U_IDLE;
            uart_start <= 1'b0;
            tx_byte    <= 8'd0;
            ack_toggle <= 1'b0;
            req_seen   <= 1'b0;
            req_meta   <= 1'b0;
            req_sync   <= 1'b0;
        end else begin
            req_meta   <= byte_toggle;
            req_sync   <= req_meta;
            uart_start <= 1'b0;

            case (u_state)
                U_IDLE: begin
                    if (req_sync != req_seen) begin
                        tx_byte    <= byte_hold;
                        req_seen   <= req_sync;
                        uart_start <= 1'b1;
                        u_state    <= U_WAIT_START;
                    end
                end

                U_WAIT_START: begin
                    if (uart_busy)
                        u_state <= U_WAIT_DONE;
                end

                U_WAIT_DONE: begin
                    if (!uart_busy) begin
                        ack_toggle <= req_seen;
                        u_state    <= U_IDLE;
                    end
                end

                default: u_state <= U_IDLE;
            endcase
        end
    end

    generate if(STREAM_OUTPUT) begin: holding_stream
    uart_stream_adapter adapter(.clk(uart_clk),.rst(uart_rst),.tx_start(uart_start),.tx_data(tx_byte),.tx_last(tx_byte==8'h0a),
        .tx(uart_txd),.busy(uart_busy),.stream_valid(stream_valid),.stream_data(stream_data),.stream_last(stream_last),.stream_ready(stream_ready));
    end else begin: physical_output
    assign stream_valid=0;assign stream_last=0;assign stream_data=0;
    uart_tx #(
        .CLK_FREQ_HZ (UART_CLK_HZ),
        .BAUD_RATE   (BAUD_RATE)
    ) uart_tx_inst (
        .clk      (uart_clk),
        .rst      (uart_rst),
        .tx_start (uart_start),
        .tx_data  (tx_byte),
        .tx       (uart_txd),
        .busy     (uart_busy)
    );
    end endgenerate

endmodule
